insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"TEN_PLUS_CLOSE","title":"¿Habrá 10 o más carreras con diferencia de 2 o menos?","description":"Se corrige con el marcador final.","category":"total","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"and","rules":[{"op":"total_gte","n":10},{"op":"margin_lte","n":2}]},"priority":0,"cooldown":2,"tags":["total"]},{"code":"FIVE_EACH_SIDE","title":"¿Los dos equipos llegan al menos a 4 y el total pasa de 9?","description":"Se corrige con el marcador final.","category":"ofensiva","difficulty":"hard","points":6,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"and","rules":[{"op":"both_gte","n":4},{"op":"total_gte","n":10}]},"priority":0,"cooldown":2,"tags":["ofensiva"]},{"code":"WINNER_EXACT_DOUBLE","title":"¿El perdedor anota 3 o más y el ganador le dobla?","description":"Se corrige con el marcador final.","category":"dificultad","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"and","rules":[{"op":"loser_gte","n":3},{"op":"winner_doubles"},{"op":"margin_gte","n":3}]},"priority":0,"cooldown":2,"tags":["dificultad"]},{"code":"MARGIN_EQ_6","title":"¿La diferencia final será de exactamente 6?","description":"Se corrige con el marcador final.","category":"diferencia","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"margin_eq","n":6},"priority":0,"cooldown":2,"tags":["diferencia"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;